(()=>{'use strict';const root=window.OpenDeskTool?.root;if(!root)return;
const sdk=window.OpenDeskSDK?.browser?.proxy?.managed;
const result=root.querySelector('#proxy-c2-result');
const config={endpoint:{scheme:'socks5',host:'proxy.fixture.test',port:18897},domains:['target.fixture.test']};
let running=false;
async function call(method){
 if(running)return;running=true;result.textContent=JSON.stringify({method,state:'pending'});
 try{
  if(!sdk)throw Object.assign(new Error('Public SDK unavailable'),{code:'E_NO_SDK'});
  const data=method==='getStatus'?await sdk.getStatus():method==='requestEnable'?
    await sdk.requestEnable({config}):await sdk.requestDisable();
  result.textContent=JSON.stringify({method,ok:true,data});
 }catch(e){result.textContent=JSON.stringify({method,ok:false,code:e?.code||'E_UNKNOWN',message:String(e?.message||e).slice(0,180)});}
 finally{running=false;}
}
for(const [id,method] of [['proxy-c2-status','getStatus'],['proxy-c2-enable','requestEnable'],['proxy-c2-disable','requestDisable']]){
 root.querySelector('#'+id)?.addEventListener('click',event=>{if(event?.isTrusted===true)void call(method);});
}
void call('getStatus');
})();
